'use strict';

// MODULES //

var getShape = require( '@stdlib/ndarray/base/shape' );
var getStrides = require( '@stdlib/ndarray/base/strides' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var strided = require( '@stdlib/blas/ext/base/cindex-of-row' ).ndarray;


// MAIN //

/**
* Returns the index of the first row in a single-precision complex floating-point input matrix which has the same elements as a provided search vector.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a two-dimensional input ndarray corresponding to `A`.
*     -   a one-dimensional input ndarray corresponding to `x`.
*     -   a one-dimensional workspace ndarray.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {integer} row index
*
* @example
* var Complex64Matrix = require( '@stdlib/ndarray/matrix/complex64' );
* var Complex64Vector = require( '@stdlib/ndarray/vector/complex64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
* var ndarray = require( '@stdlib/ndarray/ctor' );
* var cindexOfRow = require( '@stdlib/blas/ext/base/ndarray/cindex-of-row' );
*
* var A = new Complex64Matrix( [ [ 1.0, 0.0, 2.0, 0.0 ], [ 3.0, 0.0, 4.0, 0.0 ] ] );
* var x = new Complex64Vector( [ 3.0, 0.0, 4.0, 0.0 ] );
* var workspace = new ndarray( 'uint8', new Uint8Array( 2 ), [ 2 ], [ 1 ], 0, 'row-major' );
*
* var out = cindexOfRow( [ A, x, workspace ] );
* // returns 1
*/
function cindexOfRow( arrays ) {
	var workspace;
	var sh;
	var sa;
	var A;
	var x;

	A = arrays[ 0 ];
	x = arrays[ 1 ];
	workspace = arrays[ 2 ];

	sh = getShape( A, false );
	sa = getStrides( A, false );

	return strided( sh[ 0 ], sh[ 1 ], getData( A ), sa[ 0 ], sa[ 1 ], getOffset( A ), getData( x ), getStride( x, 0 ), getOffset( x ), getData( workspace ), getStride( workspace, 0 ), getOffset( workspace ) ); // eslint-disable-line max-len
}


// EXPORTS //

module.exports = cindexOfRow;

